// --- diet-safe.js
// RAM diet, safe set. All names verified in Firefox ESR 153.7.0 source.

// Fewer idle spare processes
pref("dom.ipc.processPrelaunch.fission.number", 1);
pref("browser.newtab.preload", false);

// Smaller decoded-image and media buffers
pref("image.mem.surfacecache.max_size_kb", 262144);
pref("image.mem.surfacecache.min_expiration_ms", 15000);
pref("media.memory_caches_combined_limit_kb", 131072);

// Smaller history and session state
pref("browser.sessionstore.max_tabs_undo", 5);
pref("browser.sessionhistory.max_entries", 20);

// Built-in AI and promo features off (no ML process)
pref("browser.ml.enable", false);
pref("browser.ml.chat.enabled", false);
pref("browser.ml.linkPreview.enabled", false);
pref("browser.translations.enable", false);
pref("browser.tabs.groups.smart.enabled", false);
pref("browser.vpn_promo.enabled", false);
pref("browser.topsites.contile.enabled", false);

// Fewer background calls
pref("extensions.systemAddon.update.enabled", false);
pref("services.settings.poll_interval", 604800);

// Fewer idle content processes (site isolation stays on)
pref("dom.ipc.processPrelaunch.fission.number", 0);
pref("dom.ipc.processReuse.unusedGraceMs", 1000);

// Round 2: no site breakage, no security change
pref("browser.sessionstore.max_tabs_undo", 3);
pref("browser.cache.memory.capacity", 32768);
pref("network.dnsCacheEntries", 200);
pref("gfx.content.skia-font-cache-size", 10);
pref("extensions.formautofill.addresses.enabled", false);
pref("extensions.formautofill.creditCards.enabled", false);
pref("network.captive-portal-service.enabled", false);
pref("browser.tabs.hoverPreview.enabled", false);
pref("browser.tabs.hoverPreview.showThumbnails", false);
pref("browser.sessionstore.restore_tabs_lazily", true);

// Round 3: services this browser does not use (also stops outside connections)
pref("dom.push.enabled", false);
pref("identity.fxaccounts.enabled", false);

// Round 4: background tabs give memory back
pref("dom.memory.memory_pressure_on_background", 1);
pref("dom.memory.obscurant_pageout_on_background", true);
pref("dom.memory.obscurant_pageout_delay_ms", 20000);

// Round 5: unload background tabs when the whole computer runs low on memory
// (under 20% or under 1500 MB free). Firefox's own version is off on Linux.
pref("obscurant.memory.lowmem_unload", true);
pref("obscurant.memory.low_percent", 20);
pref("obscurant.memory.low_mb", 1500);
pref("obscurant.memory.low_min_inactive_ms", 30000);
pref("obscurant.memory.min_tabs_kept", 4);

// Downloads: block files disguised as documents (no network needed).
pref("obscurant.downloads.filecheck", true);

